    ADD COLUMN IF NOT EXISTS scenario_optimistic_expense_adjustment numeric(8, 5) NOT NULL DEFAULT 0 CHECK (scenario_optimistic_expense_adjustment > -1 AND scenario_optimistic_expense_adjustment <= 10),
