    ADD COLUMN IF NOT EXISTS office_maintenance_monthly numeric(14, 2) NOT NULL DEFAULT 0 CHECK (office_maintenance_monthly >= 0),
    ADD COLUMN IF NOT EXISTS office_software_monthly numeric(14, 2) NOT NULL DEFAULT 0 CHECK (office_software_monthly >= 0),
