    ADD COLUMN IF NOT EXISTS projected_admin_salary numeric(14, 2) NOT NULL DEFAULT 0 CHECK (projected_admin_salary >= 0),
    ADD COLUMN IF NOT EXISTS projected_admin_transport numeric(14, 2) NOT NULL DEFAULT 0 CHECK (projected_admin_transport >= 0),
